package ru.forum.adbfastboottool;

import android.content.ContentProvider;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.MatrixCursor;
import android.net.Uri;
import android.os.Bundle;
import android.os.ParcelFileDescriptor;
import android.provider.OpenableColumns;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.Objects;

/**
 * Test APK only; serves generated bytes through a real Binder/FD boundary.
 * This provider runs in the test APK's own process, outside the instrumented app's
 * combined class path. Use platform/Java APIs: Kotlin lives only in the target APK.
 */
public final class FirmwareFixtureProvider extends ContentProvider {
    private volatile boolean deny;

    private File image() {
        return new File(Objects.requireNonNull(getContext()).getCacheDir(), "fixture.img");
    }

    private void reset(int size) {
        byte[] bytes = new byte[size];
        for (int i = 0; i < size; i++) bytes[i] = (byte) (i % 251);
        try (FileOutputStream out = new FileOutputStream(image())) {
            out.write(bytes);
        } catch (IOException error) {
            throw new IllegalStateException("Cannot create provider fixture", error);
        }
    }

    @Override public boolean onCreate() { reset(8192); return true; }

    @Override public Bundle call(String method, String arg, Bundle extras) {
        switch (method) {
            case "reset": deny = false; reset(8192); break;
            case "deny": deny = true; break;
            case "resize": reset(Integer.parseInt(Objects.requireNonNull(arg))); break;
            default: throw new IllegalArgumentException("Unknown fixture command");
        }
        return new Bundle();
    }

    @Override public ParcelFileDescriptor openFile(Uri uri, String mode) throws FileNotFoundException {
        if (!"r".equals(mode)) throw new FileNotFoundException("Read-only fixture");
        if (deny) throw new SecurityException("Fixture provider revoked read access");
        if ("pipe".equals(uri.getLastPathSegment())) {
            try {
                ParcelFileDescriptor[] pipe = ParcelFileDescriptor.createPipe();
                pipe[1].close();
                return pipe[0];
            } catch (IOException error) {
                FileNotFoundException failure = new FileNotFoundException("Cannot create fixture pipe");
                failure.initCause(error);
                throw failure;
            }
        }
        return ParcelFileDescriptor.open(image(), ParcelFileDescriptor.MODE_READ_ONLY);
    }

    @Override public Cursor query(Uri uri, String[] projection, String selection, String[] args, String sort) {
        String[] columns = projection != null ? projection : new String[] {OpenableColumns.DISPLAY_NAME, OpenableColumns.SIZE};
        MatrixCursor cursor = new MatrixCursor(columns);
        Object[] row = new Object[columns.length];
        for (int i = 0; i < columns.length; i++) {
            row[i] = OpenableColumns.DISPLAY_NAME.equals(columns[i]) ? "provider image.img" : 1L;
        }
        cursor.addRow(row);
        return cursor;
    }

    @Override public String getType(Uri uri) { return "application/octet-stream"; }
    @Override public Uri insert(Uri uri, ContentValues values) { throw new UnsupportedOperationException(); }
    @Override public int update(Uri uri, ContentValues values, String selection, String[] args) { throw new UnsupportedOperationException(); }
    @Override public int delete(Uri uri, String selection, String[] args) { throw new UnsupportedOperationException(); }
}
